-- Generated from the same validated rows as the CSV. Never runs automatically.
BEGIN;
SET LOCAL standard_conforming_strings = on;
SELECT pg_advisory_xact_lock(hashtext('mealsolved-recipe-import'));
CREATE TEMP TABLE incoming_recipes AS
SELECT title, description, meal_time, prep_time_mins, effort_score, servings, tags, image_url, ingredients_list, shopping_list, recipe_steps, cuisine, user_id, is_user_created, source_url, source_name FROM jsonb_populate_recordset(NULL::public.recipes, '[{"title":"Simple Vanilla Milkshake","description":"A small vanilla shake made with everyday freezer and fridge staples.","meal_time":["dessert","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["shake","smoothies-and-shakes","quick","easy","treat-cold"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/simple-vanilla-milkshake-956764265bba.jpg","ingredients_list":["1/4 cup cold milk","1 cup vanilla ice cream","1/4 teaspoon vanilla extract"],"shopping_list":["1/4 cup cold milk","1 cup vanilla ice cream","1/4 teaspoon vanilla extract"],"recipe_steps":["Measure the milk into a blender. Let the ice cream stand for 2 minutes so it is easy to scoop.","Add the ice cream and the remaining measured ingredients. Cover and blend in short bursts until the mixture is smooth and pourable.","Turn off the blender before scraping down the sides if needed. Pour into one glass and enjoy right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Easy Chocolate Milkshake","description":"Chocolate ice cream makes this two-ingredient shake easy to blend after dinner.","meal_time":["dessert","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["shake","smoothies-and-shakes","quick","easy","treat-cold"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/easy-chocolate-milkshake-3ea6cc98e181.jpg","ingredients_list":["1/4 cup cold milk","1 cup chocolate ice cream"],"shopping_list":["1/4 cup cold milk","1 cup chocolate ice cream"],"recipe_steps":["Measure the milk into a blender. Let the ice cream stand for 2 minutes so it is easy to scoop.","Add the ice cream and the remaining measured ingredients. Cover and blend in short bursts until the mixture is smooth and pourable.","Turn off the blender before scraping down the sides if needed. Pour into one glass and enjoy right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Strawberry Jam Milkshake","description":"A spoonful of strawberry jam adds berry flavor without chopping fruit.","meal_time":["dessert","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["shake","smoothies-and-shakes","quick","easy","treat-cold"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/strawberry-jam-milkshake-299bff3bbb53.jpg","ingredients_list":["1/4 cup cold milk","1 cup vanilla ice cream","1 tablespoon strawberry jam"],"shopping_list":["1/4 cup cold milk","1 cup vanilla ice cream","1 tablespoon strawberry jam"],"recipe_steps":["Measure the milk into a blender. Let the ice cream stand for 2 minutes so it is easy to scoop.","Add the ice cream and the remaining measured ingredients. Cover and blend in short bursts until the mixture is smooth and pourable.","Turn off the blender before scraping down the sides if needed. Pour into one glass and enjoy right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Cookies and Cream Milkshake","description":"Crunchy sandwich cookies turn vanilla ice cream into a quick cookies-and-cream treat.","meal_time":["dessert","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["shake","smoothies-and-shakes","quick","easy","treat-cold"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/cookies-and-cream-milkshake-711ab7b9203c.jpg","ingredients_list":["1/4 cup cold milk","1 cup vanilla ice cream","2 chocolate sandwich cookies, broken into pieces"],"shopping_list":["1/4 cup cold milk","1 cup vanil