Smoothie","description":"Banana, peanut butter and quick oats blend into an easy breakfast or snack.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/peanut-butter-banana-oat-smoothie-1d903d99c364.jpg","ingredients_list":["3/4 cup cold milk","1 medium ripe banana, peeled and sliced","2 tablespoons quick oats","1 tablespoon creamy peanut butter","1/4 cup ice cubes"],"shopping_list":["3/4 cup cold milk","1 medium ripe banana, peeled and sliced","2 tablespoons quick oats","1 tablespoon creamy peanut butter","1/4 cup ice cubes"],"recipe_steps":["Pour the milk into a blender and add the quick oats. Let them soften for 2 minutes while you peel and slice the banana.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Chocolate Banana Smoothie","description":"A ripe banana sweetens this cocoa smoothie without needing chocolate ice cream.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/chocolate-banana-smoothie-c63cdce8aab5.jpg","ingredients_list":["1/2 cup cold milk","1/4 cup plain yogurt","1 medium ripe banana, peeled and sliced","1 tablespoon unsweetened cocoa powder","1/4 cup ice cubes"],"shopping_list":["1/2 cup cold milk","1/4 cup plain yogurt","1 medium ripe banana, peeled and sliced","1 tablespoon unsweetened cocoa powder","1/4 cup ice cubes"],"recipe_steps":["Measure the liquid into a blender, then add the yogurt or other soft ingredients if listed.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Spinach Mango Smoothie","description":"Sweet mango and banana soften the flavor of a small handful of spinach.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/spinach-mango-smoothie-6ec7cfe07368.jpg","ingredients_list":["3/4 cup orange juice","1 cup frozen mango chunks","1/2 cup washed fresh baby spinach","1/2 medium ripe banana, peeled and sliced"],"shopping_list":["3/4 cup orange juice","1 cup frozen mango chunks","1/2 cup washed fresh baby spinach","1/2 medium ripe banana, peeled and sliced"],"recipe_steps":["Measure the liquid into a blender, then add the yogurt or other soft ingredients if listed.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Apple Cinnamon Oat Smoothie","description":"Unsweetened applesauce makes an easy apple smoothie with no peeling or chopping.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/apple-cinnamon-oat-smoothie-dbb96002376b.jpg","ingredients_list":["1/2 cup cold milk","1/2 cup unsweetened applesauce","1/4 cup vanilla yogurt","2 tablespoons quick oats","1/4 teaspoon ground cinnamon","1/4 cup ice cubes"],"shopping_list":["1/2 cup cold milk","1/2 cup unsweetened applesauce","1/4 cup vanilla yogurt","2 tablespoons quick oats","1/4 teaspoon ground cinnamon","1/4 cup ice cubes"],"recipe_steps":["Pour the milk into a blender and add the quick oats. Let them soften for 2 minutes, then add the applesauce and vanilla yogurt.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Raspberry Banana Smoothie","description":"Tart raspberries and a ripe banana make a simple pink smoothie with a naturally seedy texture.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/raspberry-banana-smoothie-ccec0a29290e.jpg","ingredients_list":["3/4 cup cold milk","3/4 cup frozen raspberries","1 medium ripe banana, peeled and sliced"],"shopping_list":["3/4 cup cold milk","3/4 cup frozen raspberries","1 medium ripe banana, peeled and sliced"],"recipe_steps":["Measure the liquid into a blender, then add the yogurt or other soft ingredients if listed.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null},{"title":"Orange Banana Yogurt Smoothie","description":"Orange juice, banana and vanilla yogurt make a quick creamy fruit drink.","meal_time":["breakfast","snack"],"prep_time_mins":5,"effort_score":1,"servings":1,"tags":["smoothie","smoothies-and-shakes","quick","easy"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/orange-banana-yogurt-smoothie-5225b3184226.jpg","ingredients_list":["1/2 cup orange juice","1/2 cup vanilla yogurt","1 medium ripe banana, peeled and sliced","1/4 cup ice cubes"],"shopping_list":["1/2 cup orange juice","1/2 cup vanilla yogurt","1 medium ripe banana, peeled and sliced","1/4 cup ice cubes"],"recipe_steps":["Measure the liquid into a blender, then add the yogurt or other soft ingredients if listed.","Add the fruit and all remaining measured ingredients. Cover and blend until smooth, about 45 to 60 seconds.","If the mixture stops moving, turn off the blender and scrape down the sides before blending again. Pour into one large glass and serve right away."],"cuisine":"American","user_id":null,"is_user_created":false,"source_url":null,"source_name":null}]'::jsonb);
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM incoming_recipes n JOIN public.recipes r
    ON regexp_replace(lower(r.title), '[^a-z0-9]', '', 'g') = regexp_replace(lower(n.title), '[^a-z0-9]', '', 'g') AND NOT r.is_user_created
    WHERE ROW(r.title,r.description,r.meal_time,r.prep_time_mins,r.effort_score,r.servings,r.tags,r.image_url,r.ingredients_list,r.shopping_list,r.recipe_steps,r.cuisine,r.user_id,r.is_user_created,r.source_url,r.source_name) IS DISTINCT FROM ROW(n.title,n.description,n.meal_time,n.prep_time_mins,n.effort_score,n.servings,n.tags,n.image_url,n.ingredients_list,n.shopping_list,n.recipe_steps,n.cuisine,n.user_id,n.is_user_created,n.source_url,n.source_name)) THEN
    RAISE EXCEPTION 'Existing title has different content; review before importing';
  END IF;
END $$;
INSERT INTO public.recipes (title, description, meal_time, prep_time_mins, effort_score, servings, tags, image_url, ingredients_list, shopping_list, recipe_steps, cuisine, user_id, is_user_created, source_url, source_name)
SELECT n.title, n.description, n.meal_time, n.prep_time_mins, n.effort_score, n.servings, n.tags, n.image_url, n.ingredients_list, n.shopping_list, n.recipe_steps, n.cuisine, n.user_id, n.is_user_created, n.source_url, n.source_name FROM incoming_recipes n
WHERE NOT EXISTS (SELECT 1 FROM public.recipes r WHERE NOT r.is_user_created
  AND regexp_replace(lower(r.title), '[^a-z0-9]', '', 'g') = regexp_replace(lower(n.title), '[^a-z0-9]', '', 'g'))
RETURNING id, title;
COMMIT;
